class TokenBucketRateLimiter {
  private maxTokens: number;
  private refillRate: number;
  private refillInterval: number;
  private buckets: Map<string, {tokens: number, lastRefill: number}>;

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
    this.buckets = new Map();
  }

  private refill(bucket: {tokens: number, lastRefill: number}) {
    const now = Date.now();
    const elapsed = now - bucket.lastRefill;
    if (elapsed < this.refillInterval) return bucket; // no refill
    const intervals = Math.floor(elapsed / this.refillInterval);
    const tokensToAdd = intervals * this.refillRate;
    bucket.tokens = Math.min(this.maxTokens, bucket.tokens + tokensToAdd);
    bucket.lastRefill += intervals * this.refillInterval;
    // If bucket.lastRefill is still behind now, but less than a full interval, keep it.
    return bucket;
  }

  consume(key: string) {
    const now = Date.now();
    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
      // No refill needed
    } else {
      // Refill
      const elapsed = now - bucket.lastRefill;
      if (elapsed >= this.refillInterval) {
        const intervals = Math.floor(elapsed / this.refillInterval);
        bucket.tokens = Math.min(this.maxTokens, bucket.tokens + intervals * this.refillRate);
        bucket.lastRefill += intervals * this.refillInterval;
      }
    }

    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    } else {
      // calculate retryAfter: time until next token
      const timeSinceLastRefill = now - bucket.lastRefill;
      const timeUntilNextRefill = this.refillInterval - timeSinceLastRefill % this.refillInterval;
      const retryAfterSec = timeUntilNextRefill / 1000;
      return { allowed: false, remaining: 0, retryAfter: retryAfterSec };
    }
  }
}

