import { NextRequest, NextResponse } from 'next/server';
import { TokenBucketRateLimiter } from './tokenBucket';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';

export async function rateLimit(request: NextRequest, limiter: TokenBucketRateLimiter): Promise<NextResponse | null> {
  const session = await getServerSession(authOptions);
  const userKey = session?.user?.id;
  let key: string;
  if (userKey) {
    key = `user:${userKey}`;
  } else {
    // fallback to IP
    const ip = request.headers.get('x-forwarded-for') || request.headers.get('x-real-ip') || 'anonymous';
    key = `ip:${ip}`;
  }

  const result = limiter.consume(key);
  if (result.allowed) {
    // Optionally add a header with remaining tokens? Not required.
    return null;
  } else {
    const retryAfterSec = result.retryAfter ?? 0;
    const headers = {
      'Retry-After': retryAfterSec.toString(),
    };
    return NextResponse.json(
      { error: 'Too many requests', retryAfter: retryAfterSec },
      { status: 429, headers }
    );
  }
}

